"""Core arithmetic for turning raw order data into billable amounts."""


def line_item_subtotal(unit_price, quantity):
    """Return the pre-tax, pre-discount cost of a single line item."""
    return unit_price * quantity


def apply_discount(subtotal, discount_percent):
    """Apply a percentage discount (e.g. 15 for 15%) to a subtotal."""
    return subtotal * (1 - discount_percent)


def apply_tax(amount, tax_rate_percent):
    """Apply a percentage tax rate (e.g. 8.25 for 8.25%) to an amount."""
    return amount * (1 + tax_rate_percent / 100)
